DISHES_PER_KITCHEN = 100

# A restaurant name promises a specialty: "Dosa Co." lists dosa recipes, the
# "Pizza Club" lists pizzas. Menus below are drawn from the cuisine pool and
# filtered to that family, so what the sign outside says is what the kitchen
# actually cooks.
THEME_BY_BANK = {
    1: ('pizza',),                                # Pizza Club
    2: ('burger',),                               # Bun Studio
    3: ('noodle',),                               # Wok Room
    4: ('dosa',),                                 # Dosa Co.
    5: ('taco',),                                 # Taco Social
    6: ('maki', 'roll', 'nigiri', 'sushi'),       # Sushi Garden
}
LEGACY_THEMES = {
    'bun': ('burger',),
    'ember': ('pizza',),
    'dough': ('pizza',),
    'wok': ('noodle',),
    'rice': ('rice', 'biryani', 'pulao', 'chawal'),
}

# Two real portion sizes for each dish. Both are genuine orderable variants,
# so no dish name is invented by bolting a preparation style onto a recipe.
_PORTIONS = (
    ('', 10, 'Regular portion, freshly prepared to order.'),
    (' · Sharing', 18, 'Sharing portion for two.'),
)


def menu_for(index: int, branch: int, cuisine: str | None = None,
             theme: tuple[str, ...] | None = None) -> tuple[Dish, ...]:
    """Build a kitchen's menu from real dishes in that cuisine.

    Names come from menus.py, which lists dishes a customer would actually
    recognise. When the restaurant's title names a specialty, only that family
    is served. Portion size is the only variant, so every entry is a
    legitimate order rather than an invented preparation.
    """
    recipes = CUISINE_MENUS.get(cuisine or '') or [
        (n, p, v) for n, p, v, _ in BANKS[index][3]
    ]
    if theme:
        recipes = [r for r in recipes if any(t in r[0].lower() for t in theme)]
    fallback_image = BANKS[index][2]

    # A dish is shown with its own photograph or with nothing at all. Mapping
    # "Basmati Rice" onto a gulab jamun photo misrepresents the food, and the
    # app already renders an honest placeholder when art is missing.
    result: list[Dish] = []
    seen: set[str] = set()
    for name, rupees, vegetarian in recipes:
        # A real photograph always wins when one exists for this exact dish.
        # Otherwise the illustration drawn from the dish's own name is used, so
        # a dish is never shown with someone else's photo.
        photo = dish_photo(name)
        description = f'{name}, prepared fresh to order.'
        for suffix, multiplier, note in _PORTIONS:
            full = f'{name}{suffix}'
            if full in seen or len(result) >= DISHES_PER_KITCHEN:
                continue
            seen.add(full)
            price = ((rupees + branch * 5) * multiplier // 10) * 10
            # A portion variant keeps the same photo as the base dish.
            variant_photo = dish_photo(full) if suffix == '' else photo
            result.append(Dish(full, price, vegetarian, f'{description} {note}', variant_photo))
    return tuple(result[:DISHES_PER_KITCHEN])


def build_catalog() -> tuple[Kitchen, ...]:
    result = []
    for rid, name, bank, rating, eta, old_menu in LEGACY:
        cuisine, _, image, _ = BANKS[bank]
        image = _PHOTOS['cuisines'].get(cuisine, image)
        preserved = tuple(Dish(title, price * 100, True,
                              f'{title}, freshly prepared with carefully chosen ingredients.', dish_image(title, image), available)
                          for title, price, available in old_menu)
        # Original dishes are preserved first and keep their IDs and prices.
        # The rest is filled from the recipe pool, skipping any name already
        # present so an original kitchen has no duplicate dishes either.
        taken = {p.name for p in preserved}
        filler = tuple(d for d in menu_for(bank, 0, cuisine, LEGACY_THEMES.get(rid))
                       if d.name not in taken)
        filled = (preserved + filler)[:DISHES_PER_KITCHEN]
        result.append(Kitchen(rid,name,cuisine,'Comfort food, generous portions and a little everyday joy.',preserved[0].image,
                              rating,eta,filled))
    prefixes = ['Clover','Copper','Juniper','Pepper','Maple','Olive','Golden','Moonlight','Little','Willow']
    for n in range(194):
        bank, branch = n % len(BANKS), n // len(BANKS)
        cuisine, title, image, _ = BANKS[bank]
        # Rotate through this kitchen's actual recipes instead of one generic cuisine photo.
        image = dish_image(BANKS[bank][3][branch % len(BANKS[bank][3])][0], image)
        result.append(Kitchen(f'kitchen-{n+1:03}',f'{prefixes[branch]} {title}',cuisine,
                              f'{cuisine} favourites, made with care. Discover a new daily craving.',image,
                              41 + ((n * 7) % 9),20 + ((n * 3) % 26),
                              menu_for(bank,branch,cuisine,THEME_BY_BANK.get(bank))))
    return tuple(result)

CATALOG = build_catalog()
